const query = $input.first().json.query || {};
const ok = query['hub.mode'] === 'subscribe' && $env.META_VERIFY_TOKEN && query['hub.verify_token'] === $env.META_VERIFY_TOKEN;
return [{ json: { ok, challenge: ok ? String(query['hub.challenge']) : 'forbidden' } }];

const crypto = require('crypto');
const item = $input.first();
const body = item.json.body || {};
// Reject forged deliveries when the app secret is configured.
if ($env.META_APP_SECRET) {
  const raw = item.binary?.data ? await this.helpers.getBinaryDataBuffer(0, 'data') : Buffer.from(JSON.stringify(body));
  const expected = 'sha256=' + crypto.createHmac('sha256', $env.META_APP_SECRET).update(raw).digest('hex');
  const given = item.json.headers?.['x-hub-signature-256'] || '';
  if (given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected))) {
    console.log('Rejected Meta delivery with a bad signature');
    return [];
  }
}
const provider = body.object === 'instagram' ? 'INSTAGRAM' : body.object === 'page' ? 'FACEBOOK' : null;
if (!provider) return [];
const messages = [];
for (const entry of body.entry || []) {
  for (const event of entry.messaging || []) {
    const message = event.message;
    if (!message || message.is_echo || !event.sender?.id) continue;   // our own replies come back as echoes
    const text = message.text || (message.quick_reply?.payload) || null;
    if (!text) continue;   // stickers, images: nothing to interpret
    messages.push({ json: { provider, externalUserId: event.sender.id, recipientId: event.sender.id, pageId: entry.id, displayName: null, text, mid: message.mid } });
  }
}
return messages;

const sources = $('Read Meta messages').all();
return $input.all().map((item, index) => ({ json: {
  provider: sources[index].json.provider,
  recipientId: sources[index].json.recipientId,
  text: item.json.reply,
} }));

const body = $input.first().json.body || {};
if (!body.message) {
  return [{ json: { provider: 'TEST', externalUserId: 'invalid', text: '' , invalid: true } }];
}
return [{ json: { provider: 'TEST', externalUserId: String(body.userId || 'test-user'), displayName: body.name || null, text: String(body.message) } }];
